local endless_flags={}
local INTERPOLATE=false
local STEP=18
local points={}
local function add_point(level,x,y)
points[#points+1]={id=tostring(#points+1),level=tostring(level),pos=v(x,y)}
end
for _,path in ipairs(raw_paths) do
local pts=path.pts
if INTERPOLATE then
for i=1,#pts-1 do
local a,b=pts[i],pts[i+1]
add_point(path.p,a.x,a.y)
local dx,dy=b.x-a.x,b.y-a.y
local d=math.sqrt(dx*dx+dy*dy)
local n=math.max(1,math.ceil(d/STEP))
for k=1,n-1 do
add_point(path.p,a.x+dx*k/n,a.y+dy*k/n)
end
end
if #pts>0 then
local last=pts[#pts]
add_point(path.p,last.x,last.y)
end
else
for _,p in ipairs(pts) do
add_point(path.p,p.x,p.y)
end
end
end
for _,f in ipairs(flags) do
f.pos.x=f.pos.x*SX+OFFSET.x
f.pos.y=f.pos.y*SY+OFFSET.y
end
for _,f in ipairs(endless_flags) do
f.pos.x=f.pos.x*SX+OFFSET.x
f.pos.y=f.pos.y*SY+OFFSET.y
end
for _,point in ipairs(points) do
point.pos.x=point.pos.x*SX+OFFSET.x
point.pos.y=point.pos.y*SY+OFFSET.y
end
return {flags=flags,endless_flags=endless_flags,points=points}
